import{_ as r,C as a,o as i,c as h,j as t,a as g,E as n,a2 as s}from"./chunks/framework.TaNiW7i8.js";const w=JSON.parse('{"title":"Home","description":"","frontmatter":{"title":"Home"},"headers":[],"relativePath":"en/guide/home.md","filePath":"en/guide/home.md"}'),l={name:"en/guide/home.md"};function u(c,e,d,p,m,f){const o=a("Capture");return i(),h("div",null,[e[0]||(e[0]=t("h1",{id:"home",tabindex:"-1"},[g("Home "),t("a",{class:"header-anchor",href:"#home","aria-label":'Permalink to "Home"'},"​")],-1)),e[1]||(e[1]=t("p",null,"Home is Kessho's starting screen. It answers one question: where does my memory stand? You see how big it is, how its notes link up, where they live and what has just come in.",-1)),n(o,{name:"accueil",alt:"The Kessho home screen: memory figures, the graph of its relations and the most recent entries."}),e[2]||(e[2]=s('<h2 id="what-you-see" tabindex="-1">What you see <a class="header-anchor" href="#what-you-see" aria-label="Permalink to &quot;What you see&quot;">​</a></h2><p>Home opens in the first tab, <strong>Dashboard</strong>, and reads from top to bottom, with a column on the right.</p><ul><li><strong>Header</strong>: &quot;Session open&quot;, then the <strong>Home</strong> title. On the right, the date of the last deposit and the summary &quot;13 notes · 47.1 KB&quot;.</li><li><strong>Measures band</strong>: four figures — <strong>Notes</strong>, <strong>Volume</strong>, <strong>Active projects</strong>, <strong>Domains</strong>. A dash &quot;—&quot; stands in for a figure that could not be measured.</li><li><strong>Your memory, in relations</strong>: the memory graph, with its search field (&quot;Search a note, a project…&quot;), the <strong>View as a list</strong> and <strong>Open in a tab</strong> buttons, the level filters (<strong>Domain</strong>, <strong>Concept</strong>, <strong>Project</strong>, <strong>Note</strong>, <strong>Archives</strong>) and a <strong>Reset</strong> button. The details are in <a href="/Kessho/en/guide/graph.html">Graph</a>.</li><li><strong>Zone table</strong>: one row per zone, with four columns — <strong>Memory zone</strong>, <strong>Notes</strong>, <strong>Last deposit</strong>, <strong>Density</strong>. The fullest zones come first; the &quot;(out of zone)&quot; row is always last. See <a href="/Kessho/en/guide/zones.html">Zones</a>.</li><li><strong>Recent entries</strong> (right-hand column): the sixteen most recent notes, with their date, and today&#39;s count (&quot;2 today&quot;). A memory with nothing filed shows &quot;Nothing filed yet&quot;.</li><li><strong>Memory Statistics</strong> (further down, with the <strong>Refresh</strong> button): cards, including the <strong>Active Projects Detected</strong>, shown as tags.</li><li><strong>Memory Health Score</strong>: a percentage, the number of findings (&quot;findings across N files&quot;) and how they split between what the application repairs, what to hand to an agent and what is only reported.</li><li><strong>Machine state</strong> (at the very bottom): how many connectors are configured (&quot;6 of 8 connectors configured&quot;), the version, and the <strong>Open settings</strong> button.</li></ul><p>Above the screen, a banner may appear: &quot;Migration available&quot; (a previous installation is detected, see <a href="/Kessho/en/guide/vault.html">Choose your memory</a>) or &quot;macOS is running a temporary copy&quot; (see <a href="/Kessho/en/guide/agents.html">Connect your agents</a>).</p><h3 id="around-the-home-screen" tabindex="-1">Around the home screen <a class="header-anchor" href="#around-the-home-screen" aria-label="Permalink to &quot;Around the home screen&quot;">​</a></h3><ul><li><strong>Sidebar</strong>: <strong>Context keys</strong> and <strong>Search</strong> at the top; below, <strong>Memory zones</strong> with the number of notes in each zone; at the bottom, the language selector, <strong>Help</strong> and <strong>Settings</strong>.</li><li><strong>Tab bar</strong>: home is always the first tab; zones, notes and settings open in the next ones. At the top right, your profile badge and the freshness indicator (see <a href="/Kessho/en/guide/zones.html">Zones</a>).</li><li><strong>Status bar</strong> (at the bottom): the memory&#39;s name, its number of notes, the date of the last deposit, the <strong>GIT</strong> state, the <strong>HEALTH</strong> score, the <strong>AGENTS</strong> count and the version.</li></ul><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h2><h3 id="open-a-recent-note" tabindex="-1">Open a recent note <a class="header-anchor" href="#open-a-recent-note" aria-label="Permalink to &quot;Open a recent note&quot;">​</a></h3><p>In <strong>Recent entries</strong>, click a row: the note opens in a tab. To read and edit a note, see <a href="/Kessho/en/guide/atom.html">Atom and editor</a>.</p><h3 id="explore-the-graph" tabindex="-1">Explore the graph <a class="header-anchor" href="#explore-the-graph" aria-label="Permalink to &quot;Explore the graph&quot;">​</a></h3><p>In <strong>Your memory, in relations</strong>, click <strong>Open in a tab</strong> to give it the whole screen, or <strong>View as a list</strong> to read the notes as a list rather than a drawing. See <a href="/Kessho/en/guide/graph.html">Graph</a>.</p><h3 id="refresh-the-figures" tabindex="-1">Refresh the figures <a class="header-anchor" href="#refresh-the-figures" aria-label="Permalink to &quot;Refresh the figures&quot;">​</a></h3><p>In <strong>Memory Statistics</strong>, click <strong>Refresh</strong>. The section reads the folder again (the button shows &quot;Scanning…&quot; while it reads).</p><h3 id="check-health-and-repair" tabindex="-1">Check health and repair <a class="header-anchor" href="#check-health-and-repair" aria-label="Permalink to &quot;Check health and repair&quot;">​</a></h3><p>The <strong>Memory Health Score</strong> spots defects: a broken link, an orphan note, an unreadable frontmatter, a missing zone index…</p><ol><li>Click <strong>Prepare the repair</strong>. The button is greyed out if there is nothing the application can repair by itself.</li><li>Kessho computes a plan (&quot;Computing the plan…&quot;) and sums it up: &quot;N findings repaired by N fixes across N files&quot;. <strong>Show the files</strong> unfolds the list.</li><li>Click <strong>Apply the N fixes</strong>, or <strong>Cancel</strong>. Nothing is written before that click.</li><li>The result appears (&quot;N findings repaired.&quot;) and the scan runs again.</li></ol><p>If the memory changes between the preview and your click, Kessho refuses to apply an outdated plan (&quot;The plan changed since it was shown: nothing was written&quot;) and offers <strong>Review the plan</strong>.</p><p>What the application does not repair is counted apart: &quot;N tasks for an agent&quot;. The <strong>Copy the instruction</strong> button copies the sentence to give your agent.</p><h3 id="pick-up-where-you-left-off-the-context-keys" tabindex="-1">Pick up where you left off: the context keys <a class="header-anchor" href="#pick-up-where-you-left-off-the-context-keys" aria-label="Permalink to &quot;Pick up where you left off: the context keys&quot;">​</a></h3>',19)),n(o,{name:"cles-de-contexte",alt:"The context keys screen: three projects and two domains, to hand to an agent so it finds where you left off; two projects have no summary yet, and the screen says so."}),e[3]||(e[3]=s('<ol><li>In the sidebar, click <strong>Context keys</strong>. The screen opens in a tab.</li><li>Each row of the table is a project or a domain: its title and identifier (what you give an agent), its summary, the number of archives, the date of the last session and the scope (<strong>Work</strong> or <strong>Personal</strong>). A summary that is too long is cut off: hover it to read it in full.</li><li>Narrow the list: the <strong>Filter</strong> field, <strong>Sort by</strong> (<strong>Last session</strong>, <strong>Volume</strong>, <strong>A → Z</strong>), <strong>Kind</strong> (<strong>All</strong>, <strong>Projects</strong>, <strong>Domains</strong>), <strong>Scope</strong> (<strong>All scopes</strong>, <strong>Work</strong>, <strong>Personal</strong>), and the <strong>No summary</strong> checkbox.</li><li>Click a row&#39;s title to open the project in its own tab, or <strong>Open the context</strong> to read its context file.</li></ol><p>A row without a summary shows &quot;No summary&quot;; a count at the top of the screen says how many are missing (an agent writes one with <code>mem_set_summary</code>). A context that cannot be read carries the alert &quot;Unreadable context — its frontmatter does not parse&quot;.</p><h3 id="see-where-the-connectors-stand" tabindex="-1">See where the connectors stand <a class="header-anchor" href="#see-where-the-connectors-stand" aria-label="Permalink to &quot;See where the connectors stand&quot;">​</a></h3><p>In <strong>Machine state</strong>, click <strong>Open settings</strong>: you land in the settings, where you can <a href="/Kessho/en/guide/agents.html">connect your agents</a>.</p>',4))])}const b=r(l,[["render",u]]);export{w as __pageData,b as default};
